/** Build the real supermarket-sales dataset for a project (deterministic). */
export function createSupermarketDataset(projectId: string): ProjectDataset {
  const timestamp = "2019-03-30T00:00:00.000Z";
  return {
    id: `dataset-supermarket-${projectId}`,
    projectId,
    name: "Supermarket sales (real)",
    domainId: "commerce",
    sourceKind: "csv",
    sourceMetadata: {
      kind: "knowledge_pack",
      packId: "supermarket-sales",
      label: "Supermarket sales",
      sourceName: "Kaggle: Supermarket sales (aungpyaeap)",
      sourceUrl: "https://www.kaggle.com/datasets/aungpyaeap/supermarket-sales",
      notes: "1,000 real transactions, 3 branches, 2019-01 to 2019-03. Loaded via plotly/datasets mirror.",
      useCases: ["Daily revenue vs cost", "Margin and risk briefings", "Branch performance"],
    },
    columns: COLUMNS,
    rows: SUPERMARKET_ROWS as unknown as ProjectDataset["rows"],
    createdAt: timestamp,
    updatedAt: timestamp,
  };
}
